class Solution {
    public int maxProfit(int k, int[] prices) {
        return search(prices, k, 0, 0, false);
    }

    private int search(int[] prices, int limit, int day, int completed, boolean holding) {
        if (day == prices.length) {
            return holding ? Integer.MIN_VALUE / 4 : 0;
        }
        int best = search(prices, limit, day + 1, completed, holding);
        if (!holding && completed < limit) {
            best = Math.max(best, -prices[day]
                    + search(prices, limit, day + 1, completed, true));
        } else if (holding && completed < limit) {
            best = Math.max(best, prices[day]
                    + search(prices, limit, day + 1, completed + 1, false));
        }
        return best;
    }
}

