class Solution {
    public int maxProfit(int k, int[] prices) {
        int[] cash = new int[k + 1];
        int[] hold = new int[k + 1];
        Arrays.fill(hold, Integer.MIN_VALUE / 4);
        for (int price : prices) {
            int[] nextCash = cash.clone();
            int[] nextHold = hold.clone();
            for (int transactions = 1; transactions <= k; transactions++) {
                nextHold[transactions] = Math.max(hold[transactions],
                        cash[transactions - 1] - price);
                nextCash[transactions] = Math.max(cash[transactions],
                        hold[transactions] + price);
            }
            cash = nextCash;
            hold = nextHold;
        }
        return cash[k];
    }
}
